% build_drive.m, drive_esc/Torque_Limiter
% before (revision B): tau_avail = TauMot = min(tau_lim_mot, TauThMot, TauDcm)
L(s, 'TauMot/1', 'tau_avail/1');
% after (fix pass 2026-10-23): the ESC reports its own capability only
MINMAX(s, 'TauAvail', 'min', 2);
L(s, 'TauThMot/1', 'TauAvail/1'); L(s, 'TauDcm/1', 'TauAvail/2');
L(s, 'TauAvail/1', 'tau_avail/1');

openProject('<project root>\Shaddad_UGV.prj');
% regenerate drive files after editing build_drive.m or param_drive.m
shaddad_params();                 % refresh P after a parameter change
build_drive();                    % all parts (each file is deleted and recreated)
build_drive({'esc', 'side'});     % only drive_esc and drive_side
build_tb_drive();                 % benches tb_drive, tb_drive_sys, tb_drive_2mass, tb_drive_foc
% acceptance tests (long tests are skipped unless T06_LONG = 1 when the test starts)
setenv('T06_LONG', '0');          % '1' also runs T5 (2 x 2 h), T8 (600 s) and T17
r = runtests(fullfile(currentProject().RootFolder, 'tests', 'drive', 't_drive.m'));
% one bench run: MCU-shaped 0 -> 1 m/s on the one-side bench
[c, pr] = tb_drive_profile(struct('t_end', 5, 'v_tgt', [0 0; 1 1.0]));
so = tb_drive_run('tb_drive', 5, struct('tb_cmd', c));
plot(so.truth.w_spr.Time, so.truth.w_spr.Data*P.drive.gear.r_spr); grid on
xlabel('t [s]'); ylabel('track speed [m/s]');
% same run with a modified speed loop (P overridden for this run only)
Pm = P; Pm.drive.esc.Kp_w = 0.2;
so2 = tb_drive_run('tb_drive', 5, struct('tb_cmd', c), struct('P', Pm));
